/** केंद्रकातील जोडणीयुक्त बाइटप्रवाह: स्थानिक परतमार्गाचा socket स्तर; Ethernet/TCP पाकीटसंच नाही. */
public final class प्रवाह_संचारजाळे {
    static int[] राज्य_मूल्य = new int[16], पॉर्ट_मूल्य = new int[16], जोडीबद्ध_मूल्य = new int[16], समकक्ष_पॉर्ट = new int[16], प्रतीक्षा_करा_मूल्य = new int[16], आहे_बांधलेले = new int[16];
    static int[] पुढील_मूल्य = new int[16], संख्या = new int[16], डेटा = new int[16 * 1024];
    static int पुढील_आयटम = 50000;
    static int पडताळा(int उघडलेले_संचिका_संख्या) { return उघडलेले_संचिका_संख्या >= 40 && उघडलेले_संचिका_संख्या < 56 && राज्य_मूल्य[उघडलेले_संचिका_संख्या - 40] != 0 ? उघडलेले_संचिका_संख्या - 40 : -1; }
    static boolean आहे_मध्ये_वापर(int पोर्ट_नंबर) { for (int लूप_अनुक्रमणिका = 0; लूप_अनुक्रमणिका < 16; लूप_अनुक्रमणिका++) if (राज्य_मूल्य[लूप_अनुक्रमणिका] != 0 && आहे_बांधलेले[लूप_अनुक्रमणिका] != 0 && पॉर्ट_मूल्य[लूप_अनुक्रमणिका] == पोर्ट_नंबर) return true; return false; }
    public static int प्रविष्टी_तयार_करा() {
        for (int लूप_अनुक्रमणिका = 0; लूप_अनुक्रमणिका < 16; लूप_अनुक्रमणिका++) if (राज्य_मूल्य[लूप_अनुक्रमणिका] == 0) { राज्य_मूल्य[लूप_अनुक्रमणिका] = 1; समकक्ष_पॉर्ट[लूप_अनुक्रमणिका] = पॉर्ट_मूल्य[लूप_अनुक्रमणिका] = पुढील_मूल्य[लूप_अनुक्रमणिका] = संख्या[लूप_अनुक्रमणिका] = प्रतीक्षा_करा_मूल्य[लूप_अनुक्रमणिका] = आहे_बांधलेले[लूप_अनुक्रमणिका] = 0; जोडीबद्ध_मूल्य[लूप_अनुक्रमणिका] = -1; return लूप_अनुक्रमणिका + 40; }
        return -24;
    }
    public static int बाइंड_करा_संचारटोक(int उघडलेले_संचिका_संख्या, int संचारद्वार_पत्ता, int पोर्ट_नंबर) {
        int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); if (लूप_अनुक्रमणिका < 0) return -9;
        if (संचारद्वार_पत्ता != 0 && संचारद्वार_पत्ता != 0x7f000001) return -99;
        if (राज्य_मूल्य[लूप_अनुक्रमणिका] != 1 || पोर्ट_नंबर < 0 || पोर्ट_नंबर > 65535) return -22;
        if (पोर्ट_नंबर == 0) { do { पोर्ट_नंबर = पुढील_आयटम++; if (पुढील_आयटम > 65535) पुढील_आयटम = 50000; } while (आहे_मध्ये_वापर(पोर्ट_नंबर)); }
        if (आहे_मध्ये_वापर(पोर्ट_नंबर)) return -98; पॉर्ट_मूल्य[लूप_अनुक्रमणिका] = पोर्ट_नंबर; आहे_बांधलेले[लूप_अनुक्रमणिका] = 1; राज्य_मूल्य[लूप_अनुक्रमणिका] = 2; return 0;
    }
    public static int ऐका_संचारटोक(int उघडलेले_संचिका_संख्या, int प्रलंबितरांग) { int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); if (लूप_अनुक्रमणिका < 0) return -9; if (राज्य_मूल्य[लूप_अनुक्रमणिका] != 2 || प्रलंबितरांग < 1) return -22; राज्य_मूल्य[लूप_अनुक्रमणिका] = 3; return 0; }
    public static int जोडा(int उघडलेले_संचिका_संख्या, int संचारद्वार_पत्ता, int पोर्ट_नंबर) {
        int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); if (लूप_अनुक्रमणिका < 0) return -9; if (संचारद्वार_पत्ता != 0x7f000001) return -101;
        if (पोर्ट_नंबर < 1 || पोर्ट_नंबर > 65535 || राज्य_मूल्य[लूप_अनुक्रमणिका] > 2) return -22;
        int पृष्ठ_स्वीकारा = -1; for (int आंतरिक_संयोग_स्थान = 0; आंतरिक_संयोग_स्थान < 16; आंतरिक_संयोग_स्थान++) if (राज्य_मूल्य[आंतरिक_संयोग_स्थान] == 3 && पॉर्ट_मूल्य[आंतरिक_संयोग_स्थान] == पोर्ट_नंबर) पृष्ठ_स्वीकारा = आंतरिक_संयोग_स्थान;
        if (पृष्ठ_स्वीकारा < 0) return -111;
        int आहे_रांगेतील = 0; for (int आंतरिक_संयोग_स्थान = 0; आंतरिक_संयोग_स्थान < 16; आंतरिक_संयोग_स्थान++) if (प्रतीक्षा_करा_मूल्य[आंतरिक_संयोग_स्थान] == पृष्ठ_स्वीकारा + 1) आहे_रांगेतील++;
        if (आहे_रांगेतील >= 4) return -11;
        if (राज्य_मूल्य[लूप_अनुक्रमणिका] == 1) { int प्रक्रियाकृत_मूल्य = बाइंड_करा_संचारटोक(उघडलेले_संचिका_संख्या, 0x7f000001, 0); if (प्रक्रियाकृत_मूल्य < 0) return प्रक्रियाकृत_मूल्य; }
        int दुसरे = प्रविष्टी_तयार_करा(); if (दुसरे < 0) return दुसरे; दुसरे -= 40;
        राज्य_मूल्य[लूप_अनुक्रमणिका] = राज्य_मूल्य[दुसरे] = 4; जोडीबद्ध_मूल्य[लूप_अनुक्रमणिका] = दुसरे; जोडीबद्ध_मूल्य[दुसरे] = लूप_अनुक्रमणिका; पॉर्ट_मूल्य[दुसरे] = पोर्ट_नंबर; समकक्ष_पॉर्ट[लूप_अनुक्रमणिका] = पोर्ट_नंबर; समकक्ष_पॉर्ट[दुसरे] = पॉर्ट_मूल्य[लूप_अनुक्रमणिका]; प्रतीक्षा_करा_मूल्य[दुसरे] = पृष्ठ_स्वीकारा + 1; return 0;
    }
    public static int स्वीकारा_कनेक्शन(int उघडलेले_संचिका_संख्या) { int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); if (लूप_अनुक्रमणिका < 0) return -9; if (राज्य_मूल्य[लूप_अनुक्रमणिका] != 3) return -22; for (int आंतरिक_संयोग_स्थान = 0; आंतरिक_संयोग_स्थान < 16; आंतरिक_संयोग_स्थान++) if (राज्य_मूल्य[आंतरिक_संयोग_स्थान] != 0 && प्रतीक्षा_करा_मूल्य[आंतरिक_संयोग_स्थान] == लूप_अनुक्रमणिका + 1) { प्रतीक्षा_करा_मूल्य[आंतरिक_संयोग_स्थान] = 0; return आंतरिक_संयोग_स्थान + 40; } return -11; }
    public static int लेखन(int उघडलेले_संचिका_संख्या, int प्रविष्टी_संख्या) {
        int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); if (लूप_अनुक्रमणिका < 0) return -9; if (राज्य_मूल्य[लूप_अनुक्रमणिका] != 4) return -107;
        if (प्रविष्टी_संख्या < 0 || प्रविष्टी_संख्या > 512) return -22; if (प्रविष्टी_संख्या == 0) return 0;
        int आंतरिक_संयोग_स्थान = जोडीबद्ध_मूल्य[लूप_अनुक्रमणिका]; if (आंतरिक_संयोग_स्थान < 0) return -32; int एकूण_संख्या = 1024 - संख्या[आंतरिक_संयोग_स्थान]; if (एकूण_संख्या == 0) return -11; if (एकूण_संख्या > प्रविष्टी_संख्या) एकूण_संख्या = प्रविष्टी_संख्या;
        for (int तुलना_स्थान = 0; तुलना_स्थान < एकूण_संख्या; तुलना_स्थान++) डेटा[आंतरिक_संयोग_स्थान * 1024 + (पुढील_मूल्य[आंतरिक_संयोग_स्थान] + संख्या[आंतरिक_संयोग_स्थान] + तुलना_स्थान) % 1024] = स्वपरतावा_संचारजाळे.फॉरवर्ड_मूल्य[तुलना_स्थान]; संख्या[आंतरिक_संयोग_स्थान] += एकूण_संख्या; return एकूण_संख्या;
    }
    public static int वाचन(int उघडलेले_संचिका_संख्या, int प्रविष्टी_संख्या) {
        int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); if (लूप_अनुक्रमणिका < 0) return -9; if (राज्य_मूल्य[लूप_अनुक्रमणिका] != 4) return -107; if (प्रविष्टी_संख्या < 0 || प्रविष्टी_संख्या > 512) return -22;
        if (प्रविष्टी_संख्या == 0) return 0; if (संख्या[लूप_अनुक्रमणिका] == 0) return जोडीबद्ध_मूल्य[लूप_अनुक्रमणिका] < 0 ? 0 : -11; if (प्रविष्टी_संख्या > संख्या[लूप_अनुक्रमणिका]) प्रविष्टी_संख्या = संख्या[लूप_अनुक्रमणिका];
        for (int तुलना_स्थान = 0; तुलना_स्थान < प्रविष्टी_संख्या; तुलना_स्थान++) स्वपरतावा_संचारजाळे.फॉरवर्ड_मूल्य[तुलना_स्थान] = डेटा[लूप_अनुक्रमणिका * 1024 + (पुढील_मूल्य[लूप_अनुक्रमणिका] + तुलना_स्थान) % 1024]; पुढील_मूल्य[लूप_अनुक्रमणिका] = (पुढील_मूल्य[लूप_अनुक्रमणिका] + प्रविष्टी_संख्या) % 1024; संख्या[लूप_अनुक्रमणिका] -= प्रविष्टी_संख्या; return प्रविष्टी_संख्या;
    }
    public static int संचारटोक_पॉर्ट_वाचा(int उघडलेले_संचिका_संख्या) { int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); return लूप_अनुक्रमणिका < 0 ? -9 : पॉर्ट_मूल्य[लूप_अनुक्रमणिका]; }
    public static int समकक्ष_पॉर्ट_वाचा(int उघडलेले_संचिका_संख्या) { int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); return लूप_अनुक्रमणिका < 0 ? -9 : समकक्ष_पॉर्ट[लूप_अनुक्रमणिका]; }
    public static int बंद_करा(int उघडलेले_संचिका_संख्या) {
        int लूप_अनुक्रमणिका = पडताळा(उघडलेले_संचिका_संख्या); if (लूप_अनुक्रमणिका < 0) return -9;
        if (राज्य_मूल्य[लूप_अनुक्रमणिका] == 3) for (int आंतरिक_संयोग_स्थान = 0; आंतरिक_संयोग_स्थान < 16; आंतरिक_संयोग_स्थान++) if (प्रतीक्षा_करा_मूल्य[आंतरिक_संयोग_स्थान] == लूप_अनुक्रमणिका + 1) { if (जोडीबद्ध_मूल्य[आंतरिक_संयोग_स्थान] >= 0) जोडीबद्ध_मूल्य[जोडीबद्ध_मूल्य[आंतरिक_संयोग_स्थान]] = -1; राज्य_मूल्य[आंतरिक_संयोग_स्थान] = प्रतीक्षा_करा_मूल्य[आंतरिक_संयोग_स्थान] = आहे_बांधलेले[आंतरिक_संयोग_स्थान] = 0; }
        if (जोडीबद्ध_मूल्य[लूप_अनुक्रमणिका] >= 0) जोडीबद्ध_मूल्य[जोडीबद्ध_मूल्य[लूप_अनुक्रमणिका]] = -1; राज्य_मूल्य[लूप_अनुक्रमणिका] = आहे_बांधलेले[लूप_अनुक्रमणिका] = संख्या[लूप_अनुक्रमणिका] = प्रतीक्षा_करा_मूल्य[लूप_अनुक्रमणिका] = 0; return 0;
    }
}
